// SNAPSHOT DATA REFERENSI ASLI (bukan data karangan) -- diambil langsung dari
// database lokal (sumber: modules/inventory/src/db/migrations/0007_*.sql dan
// migrasi koreksi sesudahnya) pada 2026-09-29. Dipakai sebagai pengganti
// sementara untuk endpoint GET list yang BELUM ada di backend (lihat
// docs/architecture-decisions.md § 15.1) -- kode/nama/kategori/satuan di
// bawah ini akurat dan stabil (jarang berubah), TAPI:
//   - Ini bukan live query -- kalau ada item/menu/resep baru ditambahkan
//     lewat CRUD master setelah snapshot ini, tidak akan muncul di sini
//     sampai file ini diperbarui manual atau endpoint list sungguhan dibuat.
//   - Angka HPP/harga_jual/status pending_data yang tampil di layar TETAP
//     diambil live dari API asli (getItemHpp/getMenuHpp) -- yang mock DI
//     SINI cuma daftar kode+nama+kategori untuk mengisi picker/tabel,
//     bukan angka finansial.
// JANGAN dipakai sebagai sumber kebenaran finansial -- hanya untuk
// kelengkapan tampilan daftar.

export interface MockItemRef {
  kode: string;
  name: string;
  category: string;
  type: "bahan_baku" | "packaging" | "operasional" | "setengah_jadi";
  status: "active" | "pending_data";
  recipeUnit: string;
  purchaseUnit: string | null;
  purchaseToRecipeFactor: number | null;
  hargaMaster: number | null;
  isActive: boolean;
  /** Stok minimum (ambang "menipis") dalam satuan resep. NULL kalau belum diisi --
   * berdasarkan snapshot `SELECT kode, min_stok FROM inventory_items` (2026-09-30),
   * SEMUA 92 item saat ini min_stok-nya kosong (belum pernah diisi lewat form master).
   * Ini kondisi data asli apa adanya, bukan placeholder karangan -- artinya status
   * "MENIPIS" di halaman Stok belum bisa muncul untuk item manapun sampai ada yang
   * mengisi min. stok lewat master item. */
  minStok: number | null;
}

